INSERT INTO Financial (SK_CompanyID, FI_YEAR, FI_QTR, FI_QTR_START_DATE, FI_REVENUE, FI_NET_EARN, FI_BASIC_EPS, FI_DILUT_EPS, FI_MARGIN, FI_INVENTORY, FI_ASSETS, FI_LIABILITY, FI_OUT_BASIC, FI_OUT_DILUT) SELECT CAST(COALESCE((SELECT dc.SK_CompanyID FROM DimCompany AS dc WHERE dc.CompanyID = DS.CIK AND CAST(DS.PTS AS DATE) >= dc.EffectiveDate AND (dc.EndDate IS NULL OR CAST(DS.PTS AS DATE) <= dc.EndDate) ORDER BY dc.EffectiveDate DESC LIMIT 1), (SELECT dc.SK_CompanyID FROM DimCompany AS dc WHERE dc.Name = DS.CoName AND CAST(DS.PTS AS DATE) >= dc.EffectiveDate AND (dc.EndDate IS NULL OR CAST(DS.PTS AS DATE) <= dc.EndDate) ORDER BY dc.EffectiveDate DESC LIMIT 1)) AS INT) AS SK_CompanyID, CAST(FI_YEAR AS DECIMAL(4, 0)) AS FI_YEAR, CAST(FI_QTR AS DECIMAL(1, 0)) AS FI_QTR, CAST(FI_QTR_START_DATE AS DATE) AS FI_QTR_START_DATE, CAST(FI_REVENUE AS DECIMAL(15, 2)) AS FI_REVENUE, CAST(FI_NET_EARN AS DECIMAL(15, 2)) AS FI_NET_EARN, CAST(FI_BASIC_EPS AS DECIMAL(10, 2)) AS FI_BASIC_EPS, CAST(FI_DILUT_EPS AS DECIMAL(10, 2)) AS FI_DILUT_EPS, CAST(FI_MARGIN AS DECIMAL(10, 2)) AS FI_MARGIN, CAST(FI_INVENTORY AS DECIMAL(15, 2)) AS FI_INVENTORY, CAST(FI_ASSETS AS DECIMAL(15, 2)) AS FI_ASSETS, CAST(FI_LIABILITY AS DECIMAL(15, 2)) AS FI_LIABILITY, CAST(FI_OUT_BASIC AS DECIMAL(12, 0)) AS FI_OUT_BASIC, CAST(FI_OUT_DILUT AS DECIMAL(12, 0)) AS FI_OUT_DILUT FROM (SELECT STRPTIME(PTS, '%Y%m%d-%H%M%S') AS PTS, CASE WHEN NOT TRY_CAST(CoNameOrCIK AS BIGINT) IS NULL THEN TRY_CAST(CoNameOrCIK AS BIGINT) END AS CIK, CASE WHEN TRY_CAST(CoNameOrCIK AS BIGINT) IS NULL THEN CoNameOrCIK END AS CoName, CAST(F.Year AS DECIMAL(4)) AS FI_YEAR, CAST(F.Quarter AS DECIMAL(1)) AS FI_QTR, CAST(STRPTIME(F.QtrStartDate, '%Y%m%d') AS DATE) AS FI_QTR_START_DATE, CAST(F.Revenue AS DECIMAL(15, 2)) AS FI_REVENUE, CAST(F.Earnings AS DECIMAL(15, 2)) AS FI_NET_EARN, CAST(F.EPS AS DECIMAL(10, 2)) AS FI_BASIC_EPS, CAST(F.DilutedEPS AS DECIMAL(10, 2)) AS FI_DILUT_EPS, CAST(F.Margin AS DECIMAL(10, 2)) AS FI_MARGIN, CAST(F.Inventory AS DECIMAL(15, 2)) AS FI_INVENTORY, CAST(F.Assets AS DECIMAL(15, 2)) AS FI_ASSETS, CAST(F.Liabilities AS DECIMAL(15, 2)) AS FI_LIABILITY, CAST(F.ShOut AS DECIMAL(12)) AS FI_OUT_BASIC, CAST(F.DilutedShOut AS DECIMAL(12)) AS FI_OUT_DILUT FROM Source.FinwireFIN AS F) AS DS;
